    --prefix) PREFIX="${2:-}"; shift 2 ;;
    --prefix=*) PREFIX="${1#*=}"; shift ;;
    --agent) AGENTS+=("${2:-}"); shift 2 ;;
    --agent=*) AGENTS+=("${1#*=}"); shift ;;
    --uninstall) ACTION="uninstall"; shift ;;
    --purge) PURGE=1; shift ;;
